/**
 * Signs Android release builds with your own upload key.
 *
 * `android/` is regenerated by `expo prebuild`, so the signing config is injected
 * here instead of being edited by hand. Keystore details come from Gradle
 * properties (put them in ~/.gradle/gradle.properties, never in the repo):
 *
 *   NSPLIT_UPLOAD_STORE_FILE=C:/keys/nsplit-upload.jks
 *   NSPLIT_UPLOAD_STORE_PASSWORD=...
 *   NSPLIT_UPLOAD_KEY_ALIAS=nsplit
 *   NSPLIT_UPLOAD_KEY_PASSWORD=...
 *
 * Without them, release builds keep using the debug key so builds never break.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// nsplit-release-signing';

const SIGNING_CONFIG = `
        ${MARKER}
        release {
            if (project.hasProperty('NSPLIT_UPLOAD_STORE_FILE')) {
                storeFile file(NSPLIT_UPLOAD_STORE_FILE)
                storePassword NSPLIT_UPLOAD_STORE_PASSWORD
                keyAlias NSPLIT_UPLOAD_KEY_ALIAS
                keyPassword NSPLIT_UPLOAD_KEY_PASSWORD
            }
        }`;

function addReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // 1. A `release` entry inside signingConfigs { ... }.
  const withConfig = gradle.replace(/signingConfigs\s*\{/, (match) => `${match}${SIGNING_CONFIG}`);
  if (withConfig === gradle) throw new Error('with-android-signing: signingConfigs block not found');

  // 2. The release build type uses it when the keystore is configured.
  const releaseBlock = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/;
  const withBuildType = withConfig.replace(
    releaseBlock,
    `$1signingConfig project.hasProperty('NSPLIT_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`
  );
  if (withBuildType === withConfig) throw new Error('with-android-signing: release buildType not found');
  return withBuildType;
}

module.exports = function withAndroidSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.addReleaseSigning = addReleaseSigning;
